pub fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Pre-allocate the output matrices
    let mut x_grid = Vec::with_capacity(rows);
    let mut y_grid = Vec::with_capacity(rows);

    // For each element in y, clone x for the x‐grid row
    // and repeat the y element for the y‐grid row
    for y_val in y {
        x_grid.push(x.clone());
        y_grid.push(vec![y_val; cols]);
    }

    (x_grid, y_grid)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_meshgrid_basic() {
        let x = vec![1.0, 2.0, 3.0];
        let y = vec![4.0, 5.0];
        let (xg, yg) = meshgrid(x, y);

        // xg should be 2 rows, each [1.0, 2.0, 3.0]
        assert_eq!(xg.len(), 2);
        assert_eq!(xg[0], vec![1.0, 2.0, 3.0]);
        assert_eq!(xg[1], vec![1.0, 2.0, 3.0]);

        // yg should be 2 rows, first [4.0, 4.0, 4.0], second [5.0, 5.0, 5.0]
        assert_eq!(yg.len(), 2);
        assert_eq!(yg[0], vec![4.0, 4.0, 4.0]);
        assert_eq!(yg[1], vec![5.0, 5.0, 5.0]);
    }
}